        for c in row:
            if c.value is not None:
                total_nonempty += 1
                if isinstance(c.value, str) and c.value.startswith('='):
                    total_formulas += 1
    print(ws.title, 'nonempty', total_nonempty, 'formulas', total_formulas)
    # print formula cell coordinates per column range
