for fn in ['xl/worksheets/sheet2.xml','xl/worksheets/sheet3.xml']:
    s=open(fn).read()
    rows = re.findall(r'<row r="(\d+)"[^>]*>(.*?)</row>', s, re.S)
    print('===', fn)
    for r, body in sorted(rows, key=lambda x:int(x[0])):
        empties=[]
        cells = re.findall(r'<c r="([A-Z0-9]+)"([^>]*?)(?:/>|>(.*?)</c>)', body)
